ALTER TABLE public.cv_maintenance_catalog ADD COLUMN uso_manutencao boolean NOT NULL DEFAULT true, ADD COLUMN checklist_responsaveis text[] NOT NULL DEFAULT '{}', ADD COLUMN checklist_selecionados text[] NOT NULL DEFAULT '{}', ADD COLUMN checklist_tipos text[] NOT NULL DEFAULT '{}', ADD COLUMN checklist_ordem integer NOT NULL DEFAULT 0;
ALTER TABLE public.cv_maintenance_catalog ALTER COLUMN estabelecimento_id SET DEFAULT public.get_auth_user_estabelecimento_id();
ALTER TABLE public.cv_maintenance_catalog ADD CONSTRAINT cv_catalog_checklist_responsaveis_validos CHECK (checklist_responsaveis <@ ARRAY['motorista','mecanico']::text[]), ADD CONSTRAINT cv_catalog_checklist_selecao_valida CHECK (checklist_selecionados <@ checklist_responsaveis);
INSERT INTO public.cv_maintenance_catalog (id, estabelecimento_id, tipo_veiculo, sistema, componente, acao, uso_manutencao, checklist_responsaveis, checklist_selecionados, checklist_tipos, checklist_ordem, ativo, no_roteiro)
SELECT id, estabelecimento_id, 'Todos', categoria, item, 'Verificar antes da saída', false, ARRAY[responsavel], CASE WHEN ativo THEN ARRAY[responsavel] ELSE '{}'::text[] END, tipos_veiculo, ordem, true, false FROM public.cv_checklist_saida_itens ON CONFLICT (id) DO NOTHING;
COMMENT ON TABLE public.cv_checklist_saida_itens IS 'DEPRECATED: items migrated to public.cv_maintenance_catalog checklist metadata; retained for compatibility with older clients.';